// План specs/admin-access.md, 6.1 и 6.2 (кейс AA-13). Admin «Kirill · Admin»: крошки служебных разделов как раньше. Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { ADMIN_STATE, CRUMB, expectCrumb } from './crumb-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Крошки служебных разделов — admin как раньше (#26087e6e)', () => {
  for (const lang of ['en', 'he'] as const) {
    test(`Admin opens /supportinbox and /adminpanel without redirect and sees their names in breadcrumbs (${lang.toUpperCase()}) #26087e6e @desktop @prod-safe`, async ({ page }) => {
      await setLanguage(page, lang);

      await page.goto('/supportinbox');
      await expectCrumb(page, CRUMB[lang].support);
      await expect(page).toHaveURL(/\/supportinbox(\?|#|$)/);

      await page.goto('/adminpanel');
      await expectCrumb(page, CRUMB[lang].admin);
      await expect(page).toHaveURL(/\/adminpanel(\?|#|$)/);
    });
  }
});
